2026-02-01 20:53:42 UTC:10.0.3.204(57524):yukpo_db_user@postgres:[532]:STATEMENT:  CREATE OR REPLACE FUNCTION cleanup_old_rate_limits()
	RETURNS void AS $$
	BEGIN
	    DELETE FROM rate_limit_tracking 
	    WHERE window_start < NOW() - INTERVAL '1 hour';
	END;

